// Cloudflare Worker "setting-site": serves the site and receives leads.
// assets.js is generated by `node build.mjs` from index.html + images/.
import { HTML, START, EXPLORE, ASSETS } from "./assets.js";

const TYPES = { jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png", webp: "image/webp", svg: "image/svg+xml" };

const json = (data, status = 200) =>
  new Response(JSON.stringify(data), { status, headers: { "content-type": "application/json; charset=utf-8" } });

async function handleLead(request, env, ctx) {
  let data;
  try { data = await request.json(); } catch { return json({ ok: false, error: "bad_request" }, 400); }
  if (data.website) return json({ ok: true }); // honeypot: bots fill the hidden field
  const name = String(data.name || "").trim().slice(0, 120);
  const phone = String(data.phone || "").trim().slice(0, 40);
  const field = String(data.field || "").trim().slice(0, 200);
  if (name.length < 2 || phone.replace(/\D/g, "").length < 9) return json({ ok: false, error: "invalid" }, 400);

  const row = await env.DB.prepare(
    "INSERT INTO leads (name, phone, field, user_agent, country) VALUES (?, ?, ?, ?, ?) RETURNING id"
  ).bind(name, phone, field || null, request.headers.get("user-agent") || null, request.cf?.country || null).first();

  // The email is sent by the visitor's browser (FormSubmit blocks Cloudflare's shared IPs);
  // it reports back here so email_sent / email_error stay accurate.
  return json({ ok: true, id: row.id });
}


const clip = (v, n) => String(v ?? "").trim().slice(0, n);
const html = (body, extra = {}) => new Response(body, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=300", ...extra } });

async function handleIntake(request, env) {
  let d;
  try { d = await request.json(); } catch { return json({ ok: false, error: "bad_request" }, 400); }
  const full_name = clip(d.full_name, 200), phone = clip(d.phone, 40), email = clip(d.email, 200);
  if (full_name.length < 2 || phone.replace(/\D/g, "").length < 9 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))
    return json({ ok: false, error: "invalid" }, 400);
  const locations = Array.isArray(d.locations) ? d.locations.map(x => clip(x, 60)).slice(0, 5) : [];
  const token = [...crypto.getRandomValues(new Uint8Array(16))].map(b => b.toString(16).padStart(2, "0")).join("");
  const row = await env.DB.prepare(
    `INSERT INTO intakes (token, full_name, license, locations, city, audience, help_text, approach, about, mood, phone, email)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id`
  ).bind(token, full_name, clip(d.license, 200), JSON.stringify(locations), clip(d.city, 200), clip(d.audience, 500),
         clip(d.help_text, 6000), clip(d.approach, 6000), clip(d.about, 6000), clip(d.mood, 60), phone, email).first();
  const saved = [];
  for (const f of (Array.isArray(d.files) ? d.files : []).slice(0, 2)) {
    const kind = f.kind === "logo" ? "logo" : "photo";
    const mime = /^image\/(jpeg|png|webp)$/.test(f.mime) ? f.mime : null;
    const data = typeof f.data === "string" && /^[A-Za-z0-9+/=]+$/.test(f.data) && f.data.length < 1_500_000 ? f.data : null;
    if (!mime || !data) continue;
    const r = await env.DB.prepare("INSERT INTO intake_files (intake_id, kind, mime, name, data) VALUES (?, ?, ?, ?, ?) RETURNING id")
      .bind(row.id, kind, mime, clip(f.name, 200), data).first();
    saved.push({ id: r.id, kind });
  }
  return json({ ok: true, id: row.id, token, files: saved });
}

export default {
  async fetch(request, env, ctx) {
    const path = new URL(request.url).pathname;
    if (path === "/start" || path === "/start/") return html(START, { "x-robots-tag": "noindex" });
    if (path === "/explore" || path === "/explore/") return html(EXPLORE, { "x-robots-tag": "noindex" });
    if (path === "/api/intake" && request.method === "POST") {
      try { return await handleIntake(request, env); } catch { return json({ ok: false, error: "server" }, 500); }
    }
    const ie = path.match(/^\/api\/intake\/(\d+)\/email$/);
    if (ie && request.method === "POST") {
      try {
        const r = await request.json();
        await env.DB.prepare("UPDATE intakes SET email_sent = ?, email_error = ? WHERE id = ? AND token = ? AND email_sent = 0 AND email_error IS NULL")
          .bind(r.ok ? 1 : 0, r.ok ? null : clip(r.error || "unknown", 300), Number(ie[1]), clip(r.token, 64)).run();
      } catch {}
      return json({ ok: true });
    }
    const fm = path.match(/^\/files\/([0-9a-f]{32})\/(\d+)$/);
    if (fm) {
      const f = await env.DB.prepare("SELECT f.mime, f.data FROM intake_files f JOIN intakes i ON i.id = f.intake_id WHERE i.token = ? AND f.id = ?")
        .bind(fm[1], Number(fm[2])).first();
      if (!f) return new Response("Not found", { status: 404 });
      const bytes = Uint8Array.from(atob(f.data), c => c.charCodeAt(0));
      return new Response(bytes, { headers: { "content-type": f.mime, "cache-control": "private, max-age=3600", "x-robots-tag": "noindex" } });
    }
    const m = path.match(/^\/api\/lead\/(\d+)\/email$/);
    if (m && request.method === "POST") {
      try {
        const r = await request.json();
        await env.DB.prepare("UPDATE leads SET email_sent = ?, email_error = ? WHERE id = ? AND email_sent = 0 AND email_error IS NULL")
          .bind(r.ok ? 1 : 0, r.ok ? null : String(r.error || "unknown").slice(0, 300), Number(m[1])).run();
      } catch {}
      return json({ ok: true });
    }
    if (path === "/api/lead") {
      if (request.method !== "POST") return json({ ok: false, error: "method" }, 405);
      try { return await handleLead(request, env, ctx); }
      catch { return json({ ok: false, error: "server" }, 500); }
    }
    const b64 = ASSETS[path];
    if (b64) {
      const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
      return new Response(bytes, { headers: { "content-type": TYPES[path.split(".").pop().toLowerCase()] || "application/octet-stream", "cache-control": "public, max-age=86400" } });
    }
    return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=300" } });
  },
};
